  $("#productionStockDefaultsForm")?.addEventListener("submit",saveStockParameterDefaults);$("#productionParameterSearch")?.addEventListener("input",renderStockParameters);$("#productionParameterType")?.addEventListener("change",renderStockParameters);$("#productionParameterOrigin")?.addEventListener("change",renderStockParameters);$("#productionStockParameterList")?.addEventListener("click",editStockParameter);$("#productionStockParameterForm")?.addEventListener("submit",saveStockParameter);$("#productionStockParameterForm")?.elements.useDefault.addEventListener("change",updateStockParameterForm);$("#closeProductionStockParameter")?.addEventListener("click",closeStockParameterEditor);$("#resetProductionStockParameter")?.addEventListener("click",resetStockParameter);
