function handleAdminViewChange(view){if(view==="production-access"){showScreen("access");load().catch(showError);return}if(view==="production-commissions"){showScreen("commissions");load().catch(showError);return}if(view==="production-materials"){showScreen("materials");load().catch(showError);return}if(view==="production-stock"){showScreen("stock");load().catch(showError);return}if(view==="production-stock-parameters"){showScreen("stock-parameters");load().catch(showError);return}if(view==="production-movements"){showScreen("movements");load().catch(showError);return}if(view==="production-purchasing"){showScreen("purchasing");load().catch(showError);return}if(view==="production-suppliers"){showScreen("suppliers");load().catch(showError);return}if(view==="production-recipes"){showScreen("recipes");load().catch(showError);return}if(view==="production"){showScreen("overview");load().catch(showError);return}closeMaterialEditor();closeSupplierEditor();closeRecipeEditor();closeStockEditor();closeStockParameterEditor()}
function showScreen(screen){if(screen!=="materials")closeMaterialEditor();if(screen!=="suppliers")closeSupplierEditor();if(screen!=="recipes")closeRecipeEditor();if(screen!=="stock")closeStockEditor();if(screen!=="stock-parameters")closeStockParameterEditor();state.screen=screen;document.querySelectorAll("[data-production-screen]").forEach((button)=>button.classList.toggle("is-active",button.dataset.productionScreen===screen));document.querySelectorAll("[data-production-panel]").forEach((panel)=>panel.hidden=panel.dataset.productionPanel!==screen)}
async function load(force=false){if(state.loaded&&!force)return;const [plans,reports,operators,inventory,materials,suppliers,recipes,stockParameters,suggestions,schedule,commissions]=await Promise.all([api("/api/admin/production/plans"),api("/api/admin/production/reports"),api("/api/admin/production-operators"),api("/api/admin/production/inventory"),api("/api/admin/production/materials"),api("/api/admin/production/suppliers"),api("/api/admin/production/recipes"),api("/api/admin/production/stock-parameters"),api("/api/admin/production/suggestions"),api("/api/admin/production/schedule-defaults"),api("/api/admin/production/commissions")]);state.plans=plans.plans||[];state.reports=reports.reports||[];state.operators=operators.operators||[];state.inventory=inventory.inventory||null;state.materials=materials.materials||[];state.suppliers=suppliers.suppliers||[];state.recipes=recipes.recipes||[];state.stockParameters=stockParameters.parameters||null;state.suggestions=suggestions.suggestions||null;state.schedule=schedule.schedule||null;state.commissions=commissions.commissions||null;state.loaded=true;clearProductSelection(false);renderPlanHistory();renderOperators();renderInventory();renderMaterials();renderSuppliers();renderSupplierOptions();renderRecipeOptions();renderRecipes();renderMovements();renderPurchasing();renderStockParameters();renderProductionSuggestions();renderProductionCommissions();const selected=state.plans.find((plan)=>plan.id===state.planId);if(selected)usePlan(selected);else if(state.plans.length)usePlan(state.plans[0]);else beginNewWeek() }
function handleProductSearch(){state.selectedProductId=null;$("#productionProductSelected").hidden=true;clearTimeout(state.searchTimer);const query=$("#productionProductSearch").value.trim();if(!query){state.products=[];hideProductResults();return}const container=$("#productionProductResults");container.innerHTML='<p class="admin-note">Buscando código KM...</p>';container.hidden=false;$("#productionProductSearch").setAttribute("aria-expanded","true");state.searchTimer=setTimeout(()=>searchProductionProducts(query),120)}
async function searchProductionProducts(query){const request=++state.searchRequest;try{const {products}=await api(`/api/admin/production/products?q=${encodeURIComponent(query)}`);if(request!==state.searchRequest||query!==$("#productionProductSearch").value.trim())return;state.products=products||[];renderProductResults()}catch(error){if(request!==state.searchRequest)return;state.products=[];$("#productionProductResults").innerHTML=`<p class="admin-note">${esc(error.message)}</p>`}}
function renderProductResults(){const container=$("#productionProductResults");const query=$("#productionProductSearch").value.trim();container.innerHTML=state.products.length?state.products.map((product)=>`<button class="production-product-result" type="button" role="option" data-production-product="${product.id}"><strong>${esc(product.kmCode)}</strong><span>${esc(product.name)}</span></button>`).join(""):`<p class="admin-note">${query?"No encontramos ese código KM.":"Escribí un código KM."}</p>`;container.hidden=!query;$("#productionProductSearch").setAttribute("aria-expanded",String(Boolean(query)))}
function handleProductSearchKeydown(event){if(event.key==="Escape")return hideProductResults();if(event.key==="ArrowDown"){event.preventDefault();$("#productionProductResults [data-production-product]")?.focus();return}if(event.key!=="Enter")return;event.preventDefault();if(state.products[0])selectProduct(state.products[0].id)}
function handleProductResultClick(event){const button=event.target.closest("[data-production-product]");if(button)selectProduct(Number(button.dataset.productionProduct))}
function handleProductResultKeydown(event){if(!["ArrowDown","ArrowUp"].includes(event.key))return;event.preventDefault();const buttons=[...$("#productionProductResults").querySelectorAll("[data-production-product]")];const index=buttons.indexOf(event.target.closest("[data-production-product]"));buttons[event.key==="ArrowDown"?Math.min(buttons.length-1,index+1):Math.max(0,index-1)]?.focus()}
function selectProduct(productId){const product=state.products.find((row)=>row.id===Number(productId));if(!product)return;state.selectedProductId=product.id;$("#productionProductSearch").value=product.kmCode;const selected=$("#productionProductSelected");selected.innerHTML=`<strong>${esc(product.kmCode)}</strong> · ${esc(product.name)}`;selected.hidden=false;hideProductResults();$("#productionProductQuantity").focus();$("#productionProductQuantity").select()}
function hideProductResults(){$("#productionProductResults").hidden=true;$("#productionProductSearch").setAttribute("aria-expanded","false")}
function clearProductSelection(focus=true){state.selectedProductId=null;state.products=[];state.searchRequest++;clearTimeout(state.searchTimer);$("#productionProductSearch").value="";$("#productionProductSelected").hidden=true;hideProductResults();if(focus)$("#productionProductSearch").focus()}
function addItem(){const productId=Number(state.selectedProductId||0);const quantity=Number($("#productionProductQuantity").value);if(!productId)return setMessage("Buscá y seleccioná primero un código KM.");if(!Number.isInteger(quantity)||quantity<1)return setMessage("Ingresá una cantidad mayor que cero.");if(state.items.some((item)=>item.productId===productId))return setMessage("Ese producto ya está incluido en la planificación.");const product=state.products.find((row)=>row.id===productId);const minutes=Number(product.productionMinutesPerUnit||0);state.items.push({productId,targetQuantity:quantity,suggestedQuantity:0,kmCode:product.kmCode,name:product.name,productionMinutesPerUnit:minutes,requiredHours:minutes?quantity*minutes/60:null});renderItems();setMessage("");$("#productionProductQuantity").value="1";clearProductSelection()}
