function renderItems(){const plan=currentPlan();const locked=plan?.status==="closed";$("#productionPlanItems").innerHTML=state.items.length?state.items.map((item)=>{const required=item.productionMinutesPerUnit?Number(item.targetQuantity||0)*Number(item.productionMinutesPerUnit)/60:null;return`<div class="production-plan-row ${item.carryoverQuantity?"is-carryover":""}"><div><strong>${esc(item.kmCode)}</strong>${item.carryoverQuantity?`<span class="production-carryover-badge">Arrastre ${item.carryoverQuantity} u.</span>`:""}<span>${esc(item.name)}</span>${item.suggestedQuantity?`<small>Sugerido actual: ${item.suggestedQuantity} u.</small>`:""}${item.productionMinutesPerUnit?`<small>${qty(item.productionMinutesPerUnit)} min/u. · ${qty(required)} horas requeridas</small>`:'<small class="production-time-pending">Tiempo de fabricación pendiente</small>'}${item.producedQuantity?`<small>Fabricado confirmado: ${item.producedQuantity} u. · Pendiente: ${item.remainingQuantity} u.</small>`:""}</div><input data-production-qty="${item.productId}" type="number" min="1" step="1" value="${item.targetQuantity}" ${locked?"disabled":""}><button class="ghost-button" data-remove-production="${item.productId}" type="button" ${locked?"disabled":""}>Quitar</button></div>`}).join(""):'<p class="admin-note">Agregá los productos que se fabricarán esta semana.</p>';renderPlanActions()}
function renderPlanActions(){const plan=currentPlan();const locked=plan?.status==="closed";const approved=plan&&["approved","in_progress"].includes(plan.status);const save=$("#saveProductionPlan");const approve=$("#approveProductionPlan");if(save){save.textContent=approved?"Guardar cambios":"Guardar borrador";save.disabled=locked||!state.items.length}if(approve){approve.hidden=Boolean(approved||locked);approve.disabled=!state.planId||!state.items.length||locked}}
function collectPlanItems(){state.items.forEach((item)=>{item.targetQuantity=Number(document.querySelector(`[data-production-qty="${item.productId}"]`)?.value||item.targetQuantity)})}
async function persistPlan(){const form=$("#productionPlanForm");collectPlanItems();const {plan}=await api("/api/admin/production/plans",{method:"POST",body:{weekStart:form.elements.weekStart.value,notes:form.elements.notes.value,items:state.items}});state.planId=plan.id;return plan}
async function savePlan(event){event.preventDefault();try{const plan=await persistPlan();await load(true);setMessage(["approved","in_progress"].includes(plan.status)?"Cambios guardados. El plan continúa visible en Producción.":"Borrador guardado. Revisalo y aprobalo cuando esté listo.",true)}catch(error){setMessage(error.message)}}
async function approvePlan(){if(!state.planId||!state.items.length)return;try{const plan=await persistPlan();await api(`/api/admin/production/plans/${plan.id}/approve`,{method:"POST",body:{}});await load(true);setMessage("Plan aprobado y visible para Producción.",true)}catch(error){setMessage(error.message)}}
function renderPlanHistory(){const select=$("#productionWeekSelect");if(!select)return;select.innerHTML=`<option value="">Nueva semana de trabajo</option>${state.plans.map((plan)=>`<option value="${plan.id}">${weekLabel(plan)} · ${status(plan.status)}</option>`).join("")}`;select.value=state.planId?String(state.planId):""}
function selectPlan(event){const button=event.target.closest("[data-production-plan]");if(button)usePlan(state.plans.find((plan)=>plan.id===Number(button.dataset.productionPlan)))}
function usePlan(plan){if(!plan)return;state.planId=plan.id;state.items=plan.items.map((item)=>({...item}));const form=$("#productionPlanForm");form.elements.weekStart.value=plan.weekStart;form.elements.weekStart.readOnly=true;form.elements.notes.value=plan.notes||"";$("#productionWeekStart").value=plan.weekStart;renderItems();renderPlanHistory();renderWeekWorkspace();renderReports();setMessage(`Plan ${status(plan.status)}.`)}
function currentPlan(){return state.plans.find((plan)=>plan.id===state.planId)||null}
function selectWeekById(id){const plan=state.plans.find((row)=>row.id===id);if(plan)usePlan(plan)}
function beginNewWeek(){const latest=[...state.plans].sort((a,b)=>a.weekStart.localeCompare(b.weekStart)).at(-1);let weekStart=latest?addDateDays(latest.weekStart,7):monday();if(state.plans.some((plan)=>plan.weekStart===weekStart))weekStart=monday();state.planId=null;state.items=[];state.weekTab="calendar";$("#productionWeekStart").value=weekStart;$("#productionWeekOperatorCount").value="1";const form=$("#productionPlanForm");form.elements.weekStart.value=weekStart;form.elements.weekStart.readOnly=false;form.elements.notes.value="";renderItems();renderPlanHistory();renderWeekWorkspace();renderReports();setCalendarMessage("#productionWeekCalendarMessage","")}
function moveSelectedWeek(direction){const weeks=[...state.plans].sort((a,b)=>a.weekStart.localeCompare(b.weekStart));const index=weeks.findIndex((plan)=>plan.id===state.planId);const next=weeks[index+direction];if(next)usePlan(next)}
