function renderWeekWorkspace(){const plan=currentPlan();const summary=plan?.summary||{};const statusNode=$("#productionWeekStatus");if(statusNode){statusNode.textContent=plan?status(plan.status):"Nueva semana";statusNode.className=`status-badge ${plan?.status==="closed"?"approved":plan?.status==="draft"?"pending":"approved"}`}if($("#productionWeekCapacity"))$("#productionWeekCapacity").textContent=plan?`${summary.workingDays} días · ${summary.operatorCount} operario${summary.operatorCount===1?"":"s"} · ${qty(summary.availableLaborHours)} h disponibles`:"Pendiente de guardar";const close=$("#closeProductionWeek");if(close){close.disabled=!plan||plan.status==="closed";close.textContent=plan?.status==="closed"?"Semana cerrada":"Cerrar semana y trasladar pendientes"}const requiredLabel=summary.productsWithoutTime?`${qty(summary.requiredLaborHours)} h parciales`:`${qty(summary.requiredLaborHours)} h`;const cards=plan?[["Estado",status(plan.status)],["Calendario",`${summary.workingDays} días / ${qty(summary.scheduledHours)} h`],["Operarios",summary.operatorCount],["Horas disponibles",`${qty(summary.availableLaborHours)} h`],["Horas requeridas",requiredLabel],["Sin tiempo cargado",summary.productsWithoutTime],["Objetivo",`${qty(summary.targetQuantity)} u.`],["Fabricado",`${qty(summary.producedQuantity)} u.`]]:[["Estado","Nueva semana"],["Calendario","Pendiente de guardar"],["Horas disponibles","-"],["Objetivo","0 u."]];if($("#productionWeekSummary"))$("#productionWeekSummary").innerHTML=cards.map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join("");const percent=summary.targetQuantity?Math.min(100,Math.round(summary.producedQuantity/summary.targetQuantity*100)):0;if($("#productionWeekProgressText"))$("#productionWeekProgressText").textContent=plan?`${qty(summary.producedQuantity)} de ${qty(summary.targetQuantity)} unidades · ${percent}%`:"Configurá primero la semana de trabajo";if($("#productionWeekProgressBar"))$("#productionWeekProgressBar").style.width=`${percent}%`;const alerts=[];if(!plan)alerts.push({message:"Configurá los días, horas y operarios en Calendario laboral. Después podrás cargar el plan de fabricación."});else{if(summary.productsWithoutTime)alerts.push({type:"warning",message:`${summary.productsWithoutTime} producto${summary.productsWithoutTime===1?"":"s"} del plan no tiene${summary.productsWithoutTime===1?"":"n"} tiempo cargado. Las horas requeridas son parciales.`});else if(summary.overCapacityHours>0)alerts.push({type:"danger",message:`La planificación supera la capacidad semanal por ${qty(summary.overCapacityHours)} horas-persona. Es una advertencia informativa y no bloquea el plan.`});else alerts.push({type:"success",message:`La planificación requiere ${qty(summary.requiredLaborHours)} de ${qty(summary.availableLaborHours)} horas-persona disponibles.`});if(summary.carryoverQuantity)alerts.push({message:`${qty(summary.carryoverQuantity)} unidades provienen de la semana anterior y aparecen identificadas como arrastre.`});if(!summary.scheduledHours)alerts.push({type:"warning",message:"Esta semana no tiene horas laborales habilitadas."});if(summary.submittedReports)alerts.push({message:`${summary.submittedReports} parte${summary.submittedReports===1?"":"s"} pendiente${summary.submittedReports===1?"":"s"} de revisión administrativa.`});if(plan.status!=="closed"&&summary.remainingQuantity)alerts.push({message:`Quedan ${qty(summary.remainingQuantity)} unidades del objetivo semanal. Al cerrar, el pendiente se trasladará automáticamente.`});if(plan.status==="closed")alerts.push({message:"Semana cerrada. Su calendario y sus objetivos quedaron guardados como histórico."})}if($("#productionWeekAlerts"))$("#productionWeekAlerts").innerHTML=alerts.map((alert)=>`<p class="${alert.type?`is-${alert.type}`:""}">${esc(alert.message)}</p>`).join("");renderWeekCalendar();showWeekTab(state.weekTab)}
