function calendarDaysHtml(days,prefix){return days.map((day)=>`<label class="production-week-day ${day.enabled?"is-enabled":""}"><span><input type="checkbox" data-calendar-enabled="${prefix}-${day.weekday}" ${day.enabled?"checked":""}><strong>${dayName(day.weekday)}</strong>${day.date?`<small>${formatDate(day.date)}</small>`:""}</span><span class="production-day-hours"><input type="number" min="0.5" max="24" step="0.5" value="${day.enabled?day.plannedHours:""}" data-calendar-hours="${prefix}-${day.weekday}" ${day.enabled?"":"disabled"}><em>horas</em></span></label>`).join("")}
