async function settleProductionCommissions(event){event.preventDefault();const form=event.currentTarget;const button=form.querySelector('button[type="submit"]');if(button.disabled)return;const selected=[...document.querySelectorAll("[data-production-commission-entry]:checked")];if(!selected.length)return setProductionCommissionMessage("Seleccioná al menos una comisión pendiente.");const operatorIds=new Set(selected.map((input)=>input.dataset.operatorId));if(operatorIds.size!==1)return setProductionCommissionMessage("Seleccioná comisiones de un solo operario por liquidación.");button.disabled=true;button.textContent="Liquidando...";try{await api("/api/admin/production/commission-settlements",{method:"POST",body:{entryIds:selected.map((input)=>Number(input.dataset.productionCommissionEntry)),notes:form.elements.notes.value}});form.elements.notes.value="";await load(true);setProductionCommissionMessage("Liquidación registrada correctamente.",true)}catch(error){await load(true).catch(()=>{});setProductionCommissionMessage(error.message)}finally{button.disabled=false;button.textContent="Liquidar seleccionadas"}}
