function impactLine(item,isOutput,mode){const delta=Number(item.delta??(isOutput?item.goodQuantity:0));const balance=mode==="applied"?(item.balanceAfter??item.currentBalance):item.resultingBalance;const negative=Number(balance)<0;return`<div class="production-impact-row ${negative?"is-negative":""}"><div><strong>${esc(item.itemCode||item.kmCode)}</strong><span>${esc(item.name)}</span></div><span class="production-impact-delta ${delta>=0?"is-positive":""}">${delta>=0?"+":""}${qty(delta)} ${esc(item.unit||"u.")}</span><small>${mode==="applied"?"Saldo posterior":"Quedaría"}: ${qty(balance)} ${esc(item.unit||"u.")}</small></div>`}
async function handleReport(event){
  const preview=event.target.closest("[data-preview-report]");
  const close=event.target.closest("[data-close-impact]");
  const apply=event.target.closest("[data-apply-report]");
  const returned=event.target.closest("[data-return-report]");
  try{
    if(preview){
      const id=Number(preview.dataset.previewReport);
      if(state.impacts.has(id))state.impacts.delete(id);
      else{const {impact}=await api(`/api/admin/production/reports/${id}/impact`);state.impacts.set(id,impact);}
      renderReports();return;
    }
    if(close){state.impacts.delete(Number(close.dataset.closeImpact));renderReports();return;}
    if(apply){
      const id=Number(apply.dataset.applyReport);
      if(!window.confirm("Se aplicarán exactamente los movimientos mostrados. ¿Confirmar parte?"))return;
      const result=await api(`/api/admin/production/reports/${id}/confirm`,{method:"POST",body:{}});
      state.impacts.set(id,result.impact);await load(true);return;
    }
    if(returned){
      const reason=window.prompt("Indicá claramente qué debe corregir Producción:");if(!reason)return;
      await api(`/api/admin/production/reports/${returned.dataset.returnReport}/return`,{method:"POST",body:{reason}});await load(true);
    }
  }catch(error){showError(error);}
}
